import { useState, useTransition } from "react";

function Tabs() {
  const [isPending, startTransition] = useTransition();
  const [tab, setTab] = useState("home");

  function selectTab(nextTab) {
    startTransition(() => {
      setTab(nextTab);
    });
  }

  return (
    <React.Fragment>
      <button onClick={() => selectTab("profile")}>
        Profile
      </button>

      {isPending && <p>Loading...</p>}
      <TabContent tab={tab} />
    </React.Fragment>
  );
}

